230	    private String trackingNumber; // 송장 번호
231	
232	    @Enumerated(EnumType.STRING)
233	    private ShipmentStatus status;
234	
235	
236	    public void assignOrder(Order order) {
237	        this.order = order;
238	    }
239	
240	    public void updateTrackingInfo(String courier, String trackingNumber) {
241	        this.courier = courier;
242	        this.trackingNumber = trackingNumber;
243	        this.status = ShipmentStatus.IN_TRANSIT;
244	    }
245	
246	    public void updateStatus(ShipmentStatus newStatus) {
247	        if (this.status == null || this.status.canTransitionTo(newStatus)) {
248	            this.status = newStatus;
249	        } else {
250	            throw new IllegalStateException(
251	                    "Cannot transition from " + this.status + " to " + newStatus
252	            );
253	        }
254	    }
255	}

