141	public enum ShipmentStatus {
142	    PENDING {
143	        @Override
144	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
145	            return nextStatus == SHIPPED || nextStatus == CANCELED;
146	        }
147	    },
148	    SHIPPED {
149	        @Override
150	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
151	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
152	        }
153	    },
154	    IN_TRANSIT {
155	        @Override
156	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
157	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
158	                    || nextStatus == DELIVERED;
159	        }
160	    },
161	    OUT_FOR_DELIVERY {
162	        @Override
163	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
164	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
165	        }
166	    },
167	    DELIVERED {
168	        @Override
169	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
170	            return false; // 배송 완료 이후로는 상태 전환 없음
171	        }
172	    },
173	    RETURNED {
174	        @Override
175	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
176	            return nextStatus == CANCELED;
177	        }
178	    },
179	    CANCELED {
180	        @Override
181	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
182	            return false; // 취소 이후 상태 전환 없음
183	        }
184	    },
185	    DELAYED {
186	        @Override
187	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
188	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
189	        }
190	    },
191	    FAILED_DELIVERY {
192	        @Override
193	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
194	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
195	        }
196	    };
197	
198	    public abstract boolean canTransitionTo(ShipmentStatus nextStatus);
199	}
