309	    public boolean canTransitionTo(SaleStatus newStatus) {
310	        return switch (this) {
311	            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
312	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
313	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
314	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
315	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
316	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
317	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false; // SOLD 상태에서는 다른 상태로 전환 불가
318	        };
319	    }
